import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

export default function Biology() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const [introWatched, setIntroWatched] = useState(false);

  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Check if intro was already watched
  useEffect(() => {
    const introKey = `biology_intro_watched_${user?.id || "guest"}`;
    const watched = localStorage.getItem(introKey);
    console.log("🔍 Checking intro watched status. Key:", introKey, "Value:", watched);
    if (watched) {
      console.log("✅ Intro already watched in localStorage");
      setIntroWatched(true);
    }
  }, [user]);

  useEffect(() => {
    console.log("🔄 useEffect triggered. introWatched:", introWatched, "user:", user);
    async function load() {
      try {
        // Skip fetching resources - use fallback
        const found = null; // No resource found
        setSub(found);

        // Create fallback lessons (no API call)
        const pad = [];
        for (let i = 1; i <= 10; i++) {
          let status = "locked";  // All lessons locked initially
          if (i === 1) {
            status = introWatched ? "unlocked" : "locked";  // Lesson 1 unlocks when intro is watched
            console.log(`📚 Lesson 1 status set to: ${status}`);
          }
          pad.push({ id: `local-${i}`, lesson_number: i, title: `Lesson ${i}`, status });
        }
        console.log("📚 Lessons created:", pad);
        setLessons(pad);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, [user, introWatched]);

  function markIntroWatched() {
    // Mark intro as watched in localStorage
    const introKey = `biology_intro_watched_${user?.id || "guest"}`;
    localStorage.setItem(introKey, Date.now().toString());
    console.log("✅ Intro marked as watched. Key:", introKey);

    // Set intro watched state (will trigger useEffect to update lesson 1 status)
    setIntroWatched(true);
  }

  function markLessonCompleted(lessonId) {
    setLessons((prev) => {
      const updated = prev.map((ls) => {
        if (ls.id === lessonId) {
          return { ...ls, status: "completed" };
        }
        return ls;
      });

      // Unlock next lesson if the current one is completed
      const completedLessonIndex = updated.findIndex((l) => l.id === lessonId);
      if (completedLessonIndex >= 0 && completedLessonIndex < updated.length - 1) {
        const nextLesson = updated[completedLessonIndex + 1];
        if (nextLesson.status === "locked") {
          updated[completedLessonIndex + 1] = { ...nextLesson, status: "unlocked" };
        }
      }

      return updated;
    });

    // Persist to backend if not a local lesson
    if (!String(lessonId).startsWith("local-")) {
      fetch(`http://localhost:8080/lesson_progress/complete`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user?.id, lesson_id: lessonId }),
      }).catch((e) => console.warn("Could not persist completion:", e));
    }
  }

  function viewLesson(lesson) {
    navigate(`/lesson/${lesson.id}`, { state: { lesson, subId: sub?.id } });
  }

  return (
    <div className="dashboard-page" style={{ width: "100%" }}>
      <Sidebar />
      <main className="dashboard-main" style={{ padding: "2rem", margin: "0", width: "100%", maxWidth: "100%", flex: "1 1 auto" }}>
        <header className="dashboard-header" style={{ paddingLeft: "0", paddingRight: "0", marginBottom: "2rem", display: "block" }}>
          <h1 style={{ color: "#f5f7ff", margin: "0 0 0.5rem 0" }}>Biology</h1>
          <p className="dashboard-subtitle" style={{ margin: "0" }}>Discover living systems, cells, genetics and ecology.</p>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "1.5rem", width: "100%", margin: "0" }}>
            {/* Intro video - Left side */}
            <section style={{ 
              background: "radial-gradient(circle at top, #111827, #020617)",
              border: "1px solid rgba(148, 163, 184, 0.2)",
              borderRadius: "16px",
              padding: "2rem",
              boxShadow: "0 8px 24px rgba(0, 0, 0, 0.3)",
              height: "fit-content",
              position: "sticky",
              top: "2rem"
            }}>
              <h2 style={{ fontSize: "1.4rem", margin: "0 0 1.5rem 0", color: "#f5f7ff", fontWeight: "700" }}>Intro to Biology</h2>
              <div style={{ position: "relative", paddingBottom: "56.25%", height: 0, marginBottom: "1.5rem", borderRadius: "12px", overflow: "hidden", border: "1px solid rgba(148, 163, 184, 0.2)" }}>
                <iframe
                  title="Biology Intro"
                  src="https://www.youtube.com/embed/PWGBqskV1UQ?rel=0"
                  style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}
                  frameBorder="0"
                  allowFullScreen
                />
              </div>
              {!introWatched ? (
                <button 
                  onClick={markIntroWatched}
                  style={{
                    width: "100%",
                    background: "linear-gradient(135deg, #6c5ce7, #00cec9)",
                    color: "white",
                    border: "none",
                    padding: "0.85rem 1.5rem",
                    borderRadius: "8px",
                    fontSize: "0.95rem",
                    fontWeight: "600",
                    cursor: "pointer",
                    transition: "all 300ms cubic-bezier(0.34, 1.56, 0.64, 1)",
                    boxShadow: "0 10px 25px rgba(108, 92, 231, 0.3)"
                  }}
                  onMouseEnter={(e) => e.target.style.transform = "translateY(-2px)"}
                  onMouseLeave={(e) => e.target.style.transform = "translateY(0)"}
                >
                  I've finished watching
                </button>
              ) : (
                <div style={{
                  padding: "0.85rem 1rem",
                  background: "rgba(16, 185, 129, 0.15)",
                  color: "#10b981",
                  borderRadius: "8px",
                  fontWeight: "600",
                  textAlign: "center",
                  fontSize: "0.95rem",
                  border: "1px solid rgba(16, 185, 129, 0.25)"
                }}>
                  ✓ Intro Completed
                </div>
              )}
            </section>

            {/* Lessons - Right side */}
            <section>
              {introWatched ? (
                <div>
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: "1rem", marginBottom: "1.5rem" }}>
                    <h2 style={{ fontSize: "1.4rem", margin: 0, color: "#f5f7ff", fontWeight: "700" }}>Lessons</h2>
                    <p style={{ fontSize: "0.85rem", color: "#9ca3af", margin: 0, whiteSpace: "nowrap", background: "rgba(108, 92, 231, 0.15)", padding: "0.5rem 1rem", borderRadius: "8px" }}>
                      {lessons.filter(l => l.status === "completed").length} / {lessons.length} completed
                    </p>
                  </div>
                  <ul className="lessons-grid">
                    {lessons.map((lesson) => (
                      <li key={lesson.id} className={`lesson-card ${lesson.status}`}>
                        <div className="lesson-card-number">{lesson.lesson_number}</div>
                        <div className="lesson-card-content">
                          <h3>{lesson.title}</h3>
                          <p className="lesson-status">
                            {lesson.status === "completed" && "✓ Completed"}
                            {lesson.status === "unlocked" && "Ready to start"}
                            {lesson.status === "locked" && "Locked"}
                            {lesson.status === "schedule_locked" && "Select resources"}
                          </p>
                        </div>
                        <button
                          className="lesson-card-btn"
                          disabled={lesson.status === "locked" || lesson.status === "schedule_locked"}
                          onClick={() => viewLesson(lesson)}
                        >
                          View →
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
              ) : (
                <div style={{
                  padding: "4rem 2rem",
                  textAlign: "center",
                  color: "#9ca3af",
                  background: "radial-gradient(circle at top, #111827, #020617)",
                  borderRadius: "16px",
                  border: "1px dashed rgba(148, 163, 184, 0.2)"
                }}>
                  <p style={{ fontSize: "1.1rem", margin: 0, fontWeight: "500" }}>Watch the intro video to unlock lessons →</p>
                </div>
              )}
            </section>
          </div>
        )}
      </main>
    </div>
  );
}
